/** Every sentence `/start` writes for itself, keyed by language. */
export const PAGE_COPY_BY_LANG: Localized<PageCopy> = {
  en: EN, fr: FR, de: DE, it: IT, es: ES, vi: VI, id: ID, ru: RU, te: TE, ta: TA, pa: PA, or: OR, mr: MR, ml: ML, kn: KN, gu: GU, bn: BN, "pt-PT": PT_PT, ms: MS, ca: CA, sl: SL, hr: HR, sk: SK, no: NO, fi: FI, da: DA, hu: HU, el: EL, ro: RO, cs: CS, hi: HI, th: TH, sv: SV, uk: UK, nl: NL, pl: PL, tr: TR, "zh-Hant": ZH_HANT, "zh-Hans": ZH_HANS, ko: KO, ja: JA, "pt-BR": PT_BR,
};

/** `/start`'s own words in one language. English for one nobody has written yet. */
export const pageCopyFor = (lang: Lang): PageCopy => t(lang)(PAGE_COPY_BY_LANG);

/**
 * The English, kept under its old name.
 *
 * `page.ts` builds its markup from a copy object rather than from a table lookup per string, and
 * every caller that has a language hands it `pageCopyFor(lang)`. This is what the two surfaces with
 * NO language reach for: the shell's markup tests, and the claims gate, which can only read English.
 */
export const PAGE_COPY = EN;

/**
 * The Android App Link landing's own words (ieat-app#2434). Reached when the verified https return
 * did NOT deliver into the app — unverified link, or nothing installed — its sentences say what is
 * true: the token arrived in this browser, the app does not have it, and the person's own tap on
 * the link is what carries it across. "You are signed in" would be a lie here: nobody is, yet.
 */
export interface AppLinkCopy {
  /** The heading and <title>: this is a step, not a destination. */
  title: string;
  /** The instruction above the link — the tap is theirs to make. */
  lead: string;
  /** The link itself, pointing at the same verified URL the OS refused to hand over. */
  link: string;
  /** The way out when nothing answers the tap — no install, no claim on the URL. */
  install: string;
}

